145	func cmdHandoff(dataFile string, argv []string, stdout, stderr io.Writer) int {
146		fs := newFlagSet("handoff", stderr)
147		fs.StringVar(&dataFile, "data", dataFile, "本地台账数据文件路径")
148		request := fs.String("request", "", "交接请求号（用于去重）")
149		from := fs.String("from", "", "源站点")
150		to := fs.String("to", "", "目的站点")
151		var parcels stringList
152		fs.Var(&parcels, "parcel", "包裹编号，可重复指定；集合不可为空或含重复编号")
153		if ok, code := parseFlags(fs, argv, stdout, stderr, printHandoffHelp); !ok {
154			return code
155		}
156	
157		cleanReq, err := cleanID("请求号", *request)
158		if err != nil {
159			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
160			return exitBusiness
161		}
162		cleanFrom, err := cleanID("源站点", *from)
163		if err != nil {
164			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
165			return exitBusiness
166		}
167		cleanTo, err := cleanID("目的站点", *to)
168		if err != nil {
169			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
170			return exitBusiness
171		}
172		if len(parcels) == 0 {
173			fmt.Fprintf(stderr, "%s handoff: 包裹集合不可为空，至少需要一个 --parcel\n", appName)
174			return exitBusiness
175		}
176		cleanParcels := make([]string, 0, len(parcels))
177		seen := make(map[string]bool, len(parcels))
178		for _, raw := range parcels {
179			id, err := cleanID("包裹编号", raw)
180			if err != nil {
181				fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
182				return exitBusiness
183			}
184			if seen[id] {
185				fmt.Fprintf(stderr, "%s handoff: 包裹集合中编号 %q 重复\n", appName, id)
186				return exitBusiness
187			}
188			seen[id] = true
189			cleanParcels = append(cleanParcels, id)
190		}
191		if cleanFrom == cleanTo {
192			fmt.Fprintf(stderr, "%s handoff: 源站点与目的站点不能相同（均为 %q）\n", appName, cleanFrom)
193			return exitBusiness
194		}
195	
196		store, err := Open(dataFile)
197		if err != nil {
198			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
199			return exitBusiness
200		}
201		result, replayed, err := store.Handoff(cleanReq, cleanFrom, cleanTo, cleanParcels, now())
202		if err != nil {
203			fmt.Fprintf(stderr, "%s handoff: %v\n", appName, err)
204			return exitBusiness
205		}
206	
207		headline := "交接成功"
208		if replayed {
209			headline = "交接成功（请求号重复提交，返回首次保存的结果，未再追加轨迹）"
210		}
211		fmt.Fprintf(stdout, "%s\n请求号: %s\n源站点: %s\n目的站点: %s\n包裹（%d 件）:\n",
212			headline, result.Request, result.From, result.To, len(result.Parcels))
213		for _, id := range result.Parcels {
214			fmt.Fprintf(stdout, "  - %s\n", id)
215		}
216		fmt.Fprintf(stdout, "发生时间: %s\n", result.Time.Format(timeFmt))
217		return exitOK
218	}
