785	func TestReceiptSignedAndFailed(t *testing.T) {
786		s, _ := openTempStore(t)
787		t1 := tClock(2026, 10, 5, 9, 0)
788		mustRegister(t, s, "P001", "站点A", t1)
789		mustRegister(t, s, "P002", "站点A", t1)
790		mustDispatch(t, s, "B1", "站点A", "张三", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
791	
792		// 签收：状态为已签收，站点保留。
793		t3 := tClock(2026, 10, 5, 11, 0)
794		res, replayed, err := s.Receipt("RC1", "B1", "P001", resultSigned, "", t3)
795		if err != nil || replayed {
796			t.Fatalf("签收回执应成功且非重放: %v replayed=%v", err, replayed)
797		}
798		if res.Request != "RC1" || res.Batch != "B1" || res.Parcel != "P001" || res.Result != resultSigned ||
799			res.Reason != "" || !res.Time.Equal(t3) {
800			t.Fatalf("回执结果不符: %+v", res)
801		}
802		p1, _ := s.Query("P001")
803		if p1.Status != statusSigned || p1.Station != "站点A" {
804			t.Fatalf("签收后应为已签收且站点保留: %+v", p1)
805		}
806		e1 := p1.Trail[len(p1.Trail)-1]
807		if e1.Op != "回执" || e1.Batch != "B1" || e1.Result != resultSigned || e1.Request != "RC1" || !e1.Time.Equal(t3) {
808			t.Fatalf("签收回执轨迹不符: %+v", e1)
809		}
810		if s.data.Batches["B1"].Done() {
811			t.Fatal("尚有成员未回执，批次不应完成")
812		}
813	
814		// 失败：实物回到出发站，恢复在站，轨迹带原因。
815		t4 := tClock(2026, 10, 5, 12, 0)
816		res2, _, err := s.Receipt("RC2", "B1", "P002", resultFailed, "收件人不在", t4)
817		if err != nil {
818			t.Fatal(err)
819		}
820		if res2.Reason != "收件人不在" {
821			t.Fatalf("失败回执应保留原因: %+v", res2)
822		}
823		p2, _ := s.Query("P002")
824		if p2.Status != statusInStation || p2.Station != "站点A" {
825			t.Fatalf("失败回执后应恢复在站并回到出发站: %+v", p2)
826		}
827		e2 := p2.Trail[len(p2.Trail)-1]
828		if e2.Op != "回执" || e2.Result != resultFailed || e2.Reason != "收件人不在" || e2.Request != "RC2" {
829			t.Fatalf("失败回执轨迹不符: %+v", e2)
830		}
831	
832		// 全部成员回执后批次自动完成。
833		if !s.data.Batches["B1"].Done() {
834			t.Fatal("全部成员回执后批次应自动完成")
835		}
836	
837		// 失败包裹可加入新的配送批次。
838		mustDispatch(t, s, "B2", "站点A", "李四", []string{"P002"}, tClock(2026, 10, 5, 13, 0))
839		if p, _ := s.Query("P002"); p.Status != statusDelivering {
840			t.Fatalf("失败包裹重新出站后应配送中: %+v", p)
841		}
842	}
843	
844	func TestReceiptFailuresAtomic(t *testing.T) {
845		s, path := openTempStore(t)
846		t1 := tClock(2026, 10, 5, 9, 0)
847		mustRegister(t, s, "P001", "站点A", t1)
848		mustRegister(t, s, "P002", "站点A", t1)
849		mustRegister(t, s, "P003", "站点A", t1)
850		mustDispatch(t, s, "B1", "站点A", "张三", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
851		before, err := os.ReadFile(path)
852		if err != nil {
853			t.Fatal(err)
854		}
855	
856		cases := []struct {
857			name           string
858			req, batch, id string
859		}{
860			{"批次不存在", "RC1", "NOPE", "P001"},
861			{"包裹不属于批次", "RC2", "B1", "P003"},
862		}
863		for _, c := range cases {
864			t.Run(c.name, func(t *testing.T) {
865				if _, _, err := s.Receipt(c.req, c.batch, c.id, resultSigned, "", tClock(2026, 10, 5, 11, 0)); err == nil {
866					t.Fatal("条件不满足时回执必须失败")
867				}
868				after, _ := os.ReadFile(path)
869				if string(after) != string(before) {
870					t.Fatal("失败回执不得写入数据文件")
871				}
872				if _, ok := s.data.Receipts[c.req]; ok {
873					t.Fatalf("失败的首次回执不得占用请求号 %q", c.req)
874				}
875			})
876		}
877	
878		// 包裹不在该批次配送中（P002 尚未出站进 B2 却拿 B2 回执）。
879		mustDispatch(t, s, "B2", "站点A", "李四", []string{"P003"}, tClock(2026, 10, 5, 11, 30))
880		if _, _, err := s.Receipt("RC3", "B2", "P003", resultSigned, "", tClock(2026, 10, 5, 12, 0)); err != nil {
881			t.Fatal(err)
882		}
883		// P003 已签收，换请求号在同一批次再回执：已回执，拒绝。
884		if _, _, err := s.Receipt("RC4", "B2", "P003", resultSigned, "", tClock(2026, 10, 5, 12, 30)); err == nil {
885			t.Fatal("同一批次已回执的包裹换请求号再回执必须拒绝")
886		}
887		if _, ok := s.data.Receipts["RC4"]; ok {
888			t.Fatal("被拒绝的回执不得占用请求号")
889		}
890	}
891	
892	func TestReceiptReplayAndConflict(t *testing.T) {
893		s, _ := openTempStore(t)
894		t1 := tClock(2026, 10, 5, 9, 0)
895		mustRegister(t, s, "P001", "站点A", t1)
896		mustRegister(t, s, "P002", "站点A", t1)
897		mustDispatch(t, s, "B1", "站点A", "张三", []string{"P001", "P002"}, tClock(2026, 10, 5, 10, 0))
898	
899		first, _, err := s.Receipt("RC1", "B1", "P002", resultFailed, "收件人不在", tClock(2026, 10, 5, 11, 0))
900		if err != nil {
901			t.Fatal(err)
902		}
903		// 失败包裹进入新批次后，同内容重放仍返回首次结果，不检查当前状态、不改变现状。
904		mustDispatch(t, s, "B2", "站点A", "李四", []string{"P002"}, tClock(2026, 10, 5, 12, 0))
905		again, replayed, err := s.Receipt("RC1", "B1", "P002", resultFailed, "收件人不在", tClock(2026, 10, 5, 13, 0))
906		if err != nil || !replayed || again != first {
907			t.Fatalf("同内容重复回执应重放: err=%v replayed=%v", err, replayed)
908		}
909		p2, _ := s.Query("P002")
910		if p2.Status != statusDelivering || len(p2.Trail) != 4 {
911			t.Fatalf("重放不得改变状态或追加轨迹: %+v", p2)
912		}
913		if len(s.data.Batches["B1"].Receipts) != 1 || len(s.data.Batches["B2"].Receipts) != 0 {
914			t.Fatal("重放不得改变批次进度")
915		}
916	
917		// 同请求号换内容：冲突。
918		conflicts := []struct {
919			batch, id, result, reason string
920		}{
921			{"B2", "P002", resultFailed, "收件人不在"},
922			{"B1", "P001", resultFailed, "收件人不在"},
923			{"B1", "P002", resultSigned, ""},
924			{"B1", "P002", resultFailed, "别的原因"},
925		}
926		for _, c := range conflicts {
927			if _, _, err := s.Receipt("RC1", c.batch, c.id, c.result, c.reason, tClock(2026, 10, 5, 14, 0)); err == nil {
928				t.Fatalf("请求号相同但内容不同（%+v）必须报冲突", c)
929			}
930		}
931		saved := s.data.Receipts["RC1"]
932		if saved != first || saved.Batch != "B1" || saved.Reason != "收件人不在" {
933			t.Fatalf("冲突提交不得改动已有回执结果: %+v", saved)
934		}
935	}
936	
937	func TestReceiptRequestScopeIndependent(t *testing.T) {
938		s, _ := openTempStore(t)
939		t1 := tClock(2026, 10, 5, 9, 0)
940		mustRegister(t, s, "P001", "站点A", t1)
941		mustRegister(t, s, "P002", "站点A", t1)
942		mustRegister(t, s, "P003", "站点A", t1)
943		mustHandoff(t, s, "R1", "站点A", "站点B", []string{"P001", "P002", "P003"}, tClock(2026, 10, 5, 10, 0))
944		mustDispatch(t, s, "B1", "站点B", "张三", []string{"P001", "P002", "P003"}, tClock(2026, 10, 5, 11, 0))
945		// 回执请求号单独去重，可与批次号、包裹号、交接请求号同名。
946		for i, req := range []string{"B1", "P001", "R1"} {
947			parcel := []string{"P001", "P002", "P003"}[i]
948			if _, _, err := s.Receipt(req, "B1", parcel, resultSigned, "", tClock(2026, 10, 5, 12, 0)); err != nil {
