	t3 := tClock(2026, 10, 5, 11, 0)
	res, replayed, err := s.Receipt("RC1", "B1", "P001", resultSigned, "", t3)
	if err != nil || replayed {
		t.Fatalf("签收回执应成功且非重放: %v replayed=%v", err, replayed)
	}
	if res.Request != "RC1" || res.Batch != "B1" || res.Parcel != "P001" || res.Result != resultSigned ||
