			return saved, true, nil, nil
		}
		return nil, false, nil, fmt.Errorf("回执请求号 %q 已用于一次不同的回执（批次=%q 包裹=%q 结果=%q），内容冲突",
			request, saved.Batch, saved.Parcel, saved.Result)
