		}
	}

	// 空白清洗后等价的提交视为同一请求（此处首次成功，再次提交为重放）。
	out, _, code := runCLI(t, dbPath, "receipt", "--request", " RC1 ", "--batch", " B1 ", "--parcel", " P001 ", "--result", " 签收 ")
	if code != 0 || !strings.Contains(out, "回执成功") {
