	items, err := s.ImportReceipts([]ReceiptImportRecord{
		{Request: "RC1", Batch: "B1", Parcel: "P001", Result: resultSigned},
		{Request: "RC2", Batch: "B1", Parcel: "P002", Result: resultFailed, Reason: "收件人不在"},
